const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;

  const metrics = Array.isArray(data.metrics) ? data.metrics : [];

  const latest = metrics[0] ?? {};
  const previous = metrics[1] ?? {};

  const latestViews = Number(latest.views ?? 0);
  const previousViews = Number(previous.views ?? 0);

  const latestLikes = Number(latest.likes ?? 0);
  const previousLikes = Number(previous.likes ?? 0);

  const latestComments = Number(latest.comments ?? 0);
  const previousComments = Number(previous.comments ?? 0);

  // Tính mức thay đổi
  const viewsChange = latestViews - previousViews;
  const likesChange = latestLikes - previousLikes;
  const commentsChange = latestComments - previousComments;

  // Tính tỷ lệ tăng trưởng (%)
  const viewsGrowthRate =
    previousViews > 0
      ? Number(((viewsChange / previousViews) * 100).toFixed(2))
      : 0;

  const likesGrowthRate =
    previousLikes > 0
      ? Number(((likesChange / previousLikes) * 100).toFixed(2))
      : 0;

  const commentsGrowthRate =
    previousComments > 0
      ? Number(((commentsChange / previousComments) * 100).toFixed(2))
      : 0;

  output.push({
    json: {
      // ID nội bộ của social_contents
      // Dùng cho POST /api/monitoring-alerts
      socialContentId: data.socialContentId ?? null,

      // ID video YouTube
      contentId: data.contentId ?? null,

      // Thông tin competitor
      competitorId: data.competitorId ?? null,
      competitorName: data.competitorName ?? "",

      // Platform
      platform: data.platform ?? null,

      // Nội dung
      title: data.title ?? "",

      // Views
      latest_views: latestViews,
      previous_views: previousViews,
      views_change: viewsChange,
      views_growth_rate: viewsGrowthRate,

      // Likes
      latest_likes: latestLikes,
      previous_likes: previousLikes,
      likes_change: likesChange,
      likes_growth_rate: likesGrowthRate,

      // Comments
      latest_comments: latestComments,
      previous_comments: previousComments,
      comments_change: commentsChange,
      comments_growth_rate: commentsGrowthRate,

      // Thời gian snapshot
      latest_captured_at: latest.capturedAt ?? null,
      previous_captured_at: previous.capturedAt ?? null,
    },
  });
}

return output;

const items = $input.all();

const output = [];

for (const item of items) {
  const data = item.json;
  const alerts = [];

  // Ngưỡng cảnh báo
  const VIEW_GROWTH_THRESHOLD = 1.0;      // >= 1%
  const LIKE_GROWTH_THRESHOLD = 1.0;      // >= 1%
  const COMMENT_GROWTH_THRESHOLD = 1.0;   // >= 1%

  if (Number(data.views_growth_rate ?? 0) >= VIEW_GROWTH_THRESHOLD) {
    alerts.push({
      type: "views_growth",
      message: `Views tăng ${data.views_growth_rate}%`
    });
  }

  if (Number(data.likes_growth_rate ?? 0) >= LIKE_GROWTH_THRESHOLD) {
    alerts.push({
      type: "likes_growth",
      message: `Likes tăng ${data.likes_growth_rate}%`
    });
  }

  if (Number(data.comments_growth_rate ?? 0) >= COMMENT_GROWTH_THRESHOLD) {
    alerts.push({
      type: "comments_growth",
      message: `Comments tăng ${data.comments_growth_rate}%`
    });
  }

  output.push({
    json: {
      ...data,

      alert_triggered: alerts.length > 0,
      alert_count: alerts.length,
      alerts
    }
  });
}

return output;

const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const errors = [];

  if (!data.contentId) {
    errors.push("contentId không hợp lệ");
  }

  if (data.competitorId == null) {
    errors.push("competitorId không hợp lệ");
  }

  if (!data.competitorName) {
    errors.push("competitorName không hợp lệ");
  }

  if (!data.platform) {
    errors.push("platform không hợp lệ");
  }

  if (data.latest_views == null || Number(data.latest_views) < 0) {
    errors.push("latest_views không hợp lệ");
  }

  if (data.previous_views == null || Number(data.previous_views) < 0) {
    errors.push("previous_views không hợp lệ");
  }

  if (data.views_change == null) {
    errors.push("views_change không hợp lệ");
  }

  if (
    data.alert_triggered !== true &&
    data.alert_triggered !== false
  ) {
    errors.push("alert_triggered không hợp lệ");
  }

  if (
    data.alert_count == null ||
    Number(data.alert_count) < 0
  ) {
    errors.push("alert_count không hợp lệ");
  }

  if (!Array.isArray(data.alerts)) {
    errors.push("alerts phải là array");
  }

  return {
    json: {
      ...data,
      is_valid: errors.length === 0,
      validation_errors: errors
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  return {
    json: {
      contentId: data.contentId ?? null,
      competitorId: data.competitorId ?? null,
      competitorName: data.competitorName ?? "",
      platform: data.platform ?? null,

      processing_status: "monitoring_invalid",

      validation_errors: Array.isArray(data.validation_errors)
        ? data.validation_errors
        : ["Monitoring data không hợp lệ"]
    }
  };
});
